package com.plantgrowth.forecasting.entity; import jakarta.persistence.*;import java.time.*; @Entity @Table(name="growth_records") public class GrowthRecord {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="plant_id") private Plant plant; @Column(name="measurement_timestamp") private Instant measurementTimestamp; @Column(name="plant_height_cm") private Double plantHeightCm; @Column(name="measurement_method") private String measurementMethod; private String source; @Column(name="quality_status") private String qualityStatus="VALID"; public Long getId(){return id;}public Instant getMeasurementTimestamp(){return measurementTimestamp;}public Double getPlantHeightCm(){return plantHeightCm;}public void setPlant(Plant x){plant=x;}public void setMeasurementTimestamp(Instant x){measurementTimestamp=x;}public void setPlantHeightCm(Double x){plantHeightCm=x;}public void setMeasurementMethod(String x){measurementMethod=x;}public void setSource(String x){source=x;}}
